// Reshape Google Calendar node output into the { title, start, end?, location? }
// shape the /brief/auto endpoint expects (see signal_brief/models.py:CalendarEvent).
return items.map(item => {
  const ev = item.json;
  return {
    json: {
      title: ev.summary || '(untitled event)',
      start: ev.start?.dateTime || ev.start?.date,
      end: ev.end?.dateTime || ev.end?.date || null,
      location: ev.location || null
    }
  };
});

// Collapse the per-event items from the previous node into a single
// item carrying a calendar_events ARRAY, so the next node can build one
// JSON body for the HTTP request instead of firing once per event.
const events = items.map(item => item.json);
return [{ json: { calendar_events: events } }];
